<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization__main">
      <div>
        <div class="optimization__main-manu">
          <div class="optimization__manu-item">
            <ButtonUI
              svg="back-arrow-svg"
              buttonClass="btn--second"
              @action="rejectPublication"
            />
            <p class="optimization__manu-title" v-if="dataHistoy">
              Редактирование Записей #{{ id }}
            </p>
            <p class="optimization__manu-title" v-else>Новая запись</p>
          </div>
          <div class="optimization__manu-item">
            <ButtonUI
              v-if="dataHistoy"
              svg="templates-svg"
              text="применить версию"
              buttonClass="btn--primary"
              @action="openMenu('Templates')"
            />
          </div>
        </div>
        <div class="optimization-option">
          <ul class="optimization-option__form">
            <li class="optimization-option__item">
              <span class="optimization-option__text">Идентификатор</span>
              <CustomInput
                v-model="inputId.value"
                placeholder="Введите"
                :error="inputId.error"
              />
            </li>
            <li class="optimization-option__item">
              <span class="optimization-option__text">URL</span>
              <CustomInput v-model="inputURL.value" placeholder="Введите" />
            </li>

            <li class="optimization-option__item" v-if="dataHistoy">
              <span class="optimization-option__text">Созданно</span>
              <p>{{ create }}</p>
            </li>
            <li class="optimization-option__item" v-if="dataHistoy">
              <span class="optimization-option__text">Изменено</span>
              <div class="optimization-option__item-btn">
                <span>{{ updated }}</span>
                <ButtonUI
                  svg="history-svg"
                  text="история изменений"
                  buttonClass="btn--third"
                  @action="openMenu('Reference')"
                />
              </div>
            </li>
          </ul>
        </div>
        <ul class="optimization-option__form" v-if="dataHistoy">
          <li class="optimization-option__item">
            <span class="optimization-option__text">Cорт</span>
            <CustomInput
              v-model="inputSort.value"
              :text="inputSort.error ? inputSort.errorText : inputSort.text"
              :placeholder="inputSort.placeholder"
              :error="inputSort.error"
              :success="inputSort.success"
            />
          </li>
        </ul>
        <ul class="optimization-option__form">
          <li class="optimization-option__item">
            <span class="optimization-option__text">Раздел</span>
            <CustomSelect
              v-model="selectRole"
              :options="selectRoles"
              :success="selectRole.success"
              placeholder="выберите"
              :error="selectRole.error"
              :text="selectText"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Noindex</span>
            <CheckboxUINEW
              v-model="notindex.value"
              :label="notindex.lable"
              :showLabel="notindex.showLabel"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Город</span>
            <CustomSelectSearch
              v-if="!dataHistoy"
              v-model="selectedLocation"
              :options="locationOptions"
            />
            <CustomInput
              v-else
              v-model="inputCity.value"
              :text="inputCity.error ? inputCity.errorText : inputCity.text"
              :placeholder="inputCity.placeholder"
              :error="inputCity.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">H1</span>
            <CustomInput
              v-model="inputH1.value"
              :text="inputH1.error ? inputH1.errorText : inputH1.text"
              :placeholder="inputH1.placeholder"
              :error="inputH1.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Title</span>
            <CustomInput
              v-model="inputTitle.value"
              :text="inputTitle.error ? inputTitle.errorText : inputTitle.text"
              :placeholder="inputTitle.placeholder"
              :error="inputTitle.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Description</span>
            <CutomTextArea
              v-model="inputDescription.value"
              :text="
                inputDescription.error
                  ? inputDescription.errorText
                  : inputDescription.text
              "
              :placeholder="inputDescription.placeholder"
              :error="inputDescription.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Keywords</span>
            <CutomTextArea
              v-model="inputKeywords.value"
              :text="
                inputKeywords.error
                  ? inputKeywords.errorText
                  : inputKeywords.text
              "
              :placeholder="inputKeywords.placeholder"
              :error="inputKeywords.error"
            />
          </li>
          <!-- <span :class="{ 'limit-reached': isLimitReached }">
            {{ inputKeywords.value }} / {{ maxLength }}
          </span> -->
          <li class="optimization-option__item">
            <span class="optimization-option__text">SEO текст</span>
            <CutomTextArea
              v-model="inputTextSEO.value"
              :text="
                inputTextSEO.error ? inputTextSEO.errorText : inputTextSEO.text
              "
              :placeholder="inputTextSEO.placeholder"
              :error="inputTextSEO.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Header</span>
            <CutomTextArea
              v-model="inputHeader.value"
              :text="
                inputHeader.error ? inputHeader.errorText : inputHeader.text
              "
              :placeholder="inputHeader.placeholder"
              :error="inputHeader.error"
            />
          </li>
          <li class="optimization-option__item">
            <span class="optimization-option__text">Footer</span>
            <CutomTextArea
              v-model="inputFooter.value"
              :text="
                inputFooter.error ? inputFooter.errorText : inputFooter.text
              "
              :placeholder="inputFooter.placeholder"
              :error="inputFooter.error"
            />
          </li>
        </ul>
      </div>
      <CustomMenu
        v-if="isMenuOpen"
        :name="menuName"
        @closing="isMenuOpen = false"
      />
      <div class="optimization-option__btn-box" v-if="isFormChanged">
        <ButtonUI
          text="Сохранить"
          buttonClass="btn--primary"
          @action="saveForm()"
        />
        <ButtonUI
          text="Сохранить как шаблон"
          buttonClass="btn--second"
          @action="openMenu('Templates')"
        />
        <ButtonUI text="Отменить" buttonClass="btn--second" />
      </div>
    </div>
    <template v-if="showExitConfirm">
      <div class="modal-overlay">
        <div class="modal-window">
          <p class="modal-title">
            Вы уверены, что хотите покинуть страницу? Несохраненные данные будут
            потеряны.
          </p>
          <div class="modal-actions">
            <ButtonUI
              :buttonClass="`btn--second`"
              text="Всё равно покинуть"
              @click="confirmExit"
              :loading="isloading"
            />
            <ButtonUI
              text="Продолжить"
              @click="cancelExit"
              :loading="isloading"
            />
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';
// components
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import ButtonUI from '@/components/UI/ButtonUI';
import CustomInput from '@/components/UI/CustomInput';
import CutomTextArea from '@/components/UI/CutomTextArea';
import CheckboxUINEW from '@/components/UI/CheckboxUINEW';
import CustomSelect from '@/components/UI/CustomSelect';
import CustomSelectSearch from '@/components/UI/CustomSelectSearch';
import CustomMenu from '@/components/Menu/CustomMenu.vue';
import { FORMATER } from '@/composables/formater.js';
//   getSeoPageLog,
import {
  getSeoPage,
  getFilterOption,
  getRegions,
  updateSeoPage,
  createNewSeoPage,
} from '@/services/apiClient.js';

import { useRoute, useRouter } from 'vue-router';
import { isEqual } from 'lodash';

import { useValidate } from '@/composables/useValidate.js';

const router = useRouter();
const route = useRoute();

const title = ref('SEO Cтраниц');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const dataHistoy = ref(false);
const showExitConfirm = ref('');
const loading = ref(false);

const isMenuOpen = ref(false);
const menuName = ref('Templates');

const id = ref(route.params.id);

const selectedLocation = ref('');
const locationOptions = ref([]);

const create = ref('');
const updated = ref('');

const selectRoles = ref([]);
const sectionOption = ref(null);
const sectionId = ref();
const cityId = ref();

const notindex = ref({
  lable: 'да',
  value: false,
  showLabel: true,
  validateType: 'checkbox',
});
const initialValues = ref(null);
const inputSort = ref({
  value: '',
  placeholder: 'Сортировка',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputCity = ref({
  value: '',
  placeholder: 'города',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputH1 = ref({
  value: '',
  placeholder: 'H1',
  name: 'Введите H1',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputTitle = ref({
  value: '',
  placeholder: 'Title',
  text: '',
  errorText: '',
  validateType: 'empty',
  error: false,
  success: false,
});
const selectRole = ref({
  name: '',
  code: '',
  validateType: 'select',
  error: false,
});
const inputId = ref({
  value: '',
  placeholder: 'Введите',
  text: '',
  errorText: '',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputURL = ref({
  value: '',
  placeholder: 'Введите',
  text: '',
  errorText: '',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputDescription = ref({
  value: '',
  placeholder: 'Description',
  text: '',
  errorText: '',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputKeywords = ref({
  value: '',
  placeholder: 'Keywords',
  errorText: '',
  validateType: 'empty',
  error: false,
  success: false,
});
const inputTextSEO = ref({
  value: '',
  placeholder: 'Тектс СЕО',
  validateType: 'empty',
  errorText: '',
  error: false,
  success: false,
});
const inputHeader = ref({
  value: '',
  placeholder: 'Header',
  validateType: 'empty',
  text: '',
  errorText: '',
  error: false,
  success: false,
});
const inputFooter = ref({
  value: '',
  placeholder: 'Footer',
  validateType: 'empty',
  text: '',
  errorText: '',
  error: false,
  success: false,
});

const currentFormValues = computed(() => ({
  is_no_index: notindex.value.value,
  sort: 200,
  h1: inputH1.value.value,
  title: inputTitle.value.value,
  description: inputDescription.value.value,
  city_id: selectedLocation.value,
  keywords: inputKeywords.value.value,
  seo_text: inputTextSEO.value.value,
  header: inputHeader.value.value,
  footer: inputFooter.value.value,
  section_id: selectRole.value.code,
  created_at: create.value,
  updated_at: updated.value,
}));

const isFormChanged = computed(() => {
  return !isEqual(initialValues.value, currentFormValues.value);
});
const checkIdItem = async () => {
  if (id.value === 'new') {
    initialValues.value = {
      is_no_index: false,
      sort: 200,
      h1: '',
      title: '',
      description: '',
      city_id: '',
      keywords: '',
      seo_text: '',
      header: '',
      footer: '',
      section_id: '',
      created_at: '',
      updated_at: '',
    };
  } else {
    // const history = await getSeoPageLog(id.value);
    const data = await getSeoPage(id.value);

    selectRole.value = {
      code: data.data.section.id,
      name: data.data.section.title,
      ValidateType: 'select',
    };
    notindex.value.value = !!data?.data?.is_no_index;
    inputH1.value.value = data?.data?.h1;
    inputSort.value.value = data?.data?.sort;
    inputTitle.value.value = data?.data?.title;
    inputCity.value.value = data?.data?.city?.title;
    cityId.value = data?.data?.city?.id;
    sectionId.value = data?.data?.section?.id;
    sectionOption.value = data?.data?.section;
    inputDescription.value.value = data.data.description;
    inputKeywords.value.value = data.data.keywords;
    inputTextSEO.value.value = data.data.seo_text;
    inputHeader.value.value = data.data.header;
    inputFooter.value.value = data.data.footer;
    create.value = formatDateTime(data.data.created_at);
    updated.value = formatDateTime(data.data.updated_at);

    initialValues.value = {
      is_no_index: data?.data.is_no_index,
      sort: data?.data.sort,
      h1: data?.data.h1,
      title: data?.data.title,
      description: data?.data.description,
      city_id: data?.data?.city?.id,
      keywords: data.data.keywords,
      seo_text: data.data.seo_text,
      header: data.data.header,
      footer: data.data.footer,
      section_id: data.data.section.id.toString(),
      created_at: formatDateTime(data.data.created_at),
      updated_at: formatDateTime(data.data.updated_at),
    };
    if (data) {
      dataHistoy.value = true;
    }
  }
};

const saveForm = async () => {
  const isValidateStatus = useValidate([
    selectRole?.value,
    inputId?.value,
    inputH1.value,
    inputTitle.value,
    inputDescription.value,
    inputKeywords.value,
    inputDescription.value,
    inputHeader.value,
    inputFooter.value,
    inputTextSEO.value,
  ]);

  if (!isValidateStatus) return;

  const formData = new FormData();
  formData.append('id', inputId?.value.value);
  formData.append('is_no_index', FORMATER('togller', notindex.value.value));
  formData.append('sort', inputSort.value.value || 200);
  formData.append('h1', inputH1.value.value);
  formData.append('title', inputTitle.value.value);
  formData.append('description', inputDescription.value.value);
  formData.append('section_id', selectRole.value.code);
  formData.append('keywords', inputKeywords.value.value);
  formData.append('seo_text', inputTextSEO.value.value);
  formData.append('header', inputHeader.value.value);
  formData.append('footer', inputFooter.value.value);
  if (cityId.value) {
    formData.append('city_id', cityId.value);
  } else formData.append('is_no_indicate_city', 1);

  loading.value = true;
  if (id.value === 'new') {
    const res = createNewSeoPage(formData);
    if (res) {
      loading.value = false;
    }
    if (res.success !== false) {
      router.back();
    }
  } else {
    const res = updateSeoPage(id.value, formData);
    if (res) {
      loading.value = false;
    }
    if (res.success !== false) {
      router.back();
    }
  }
};
const formatDateTime = (original) => {
  const [date, time] = original.split(' ');
  const [year, month, day] = date.split('-');
  return `${year}.${month}.${day} || ${time}`;
};

const getSections = async () => {
  const data = await getFilterOption();
  selectRoles.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
};
const openMenu = (name) => {
  menuName.value = name;
  isMenuOpen.value = true;
};
const getlocation = async () => {
  const response = await getRegions();

  locationOptions.value = response;
};
//   checkIdItem();

const rejectPublication = () => {
  if (isFormChanged.value) {
    showExitConfirm.value = true;
  } else {
    router.back();
  }
};

const confirmExit = () => {
  showExitConfirm.value = false;
  router.back();
};

const cancelExit = () => {
  showExitConfirm.value = false;
};
onMounted(() => {
  getSections();
  checkIdItem();
  getlocation();
});
</script>

<style scoped lang="scss">
.optimization {
  margin: 16px 24px 16px 24px;
  display: flex;
  flex-direction: column;
  width: calc(100% - 50px);
  margin-top: 0;
  @media (max-width: 1024px) {
    height: calc(100vh - 60px);

    margin-top: 85px;
  }
  &__header {
    margin-bottom: 20px;
  }
  &__main {
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    // margin: 16px 12px 16px 0px;
    padding: 12px 24px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: calc(100vh - 120px);
    @media (max-width: 1024px) {
      margin: 16px 12px 16px 12px;
    }
    &-manu {
      display: flex;
      justify-content: space-between;
      margin-bottom: 16px;
    }
  }
  &__manu-item {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  &__manu-title {
    font-size: 16px;
    font-weight: 700;
    color: #003bce;
  }

  &-option {
    display: flex;
    flex-direction: column;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 16px 0;
    padding: 12px 24px;
    @media (max-width: 1024px) {
      margin: 16px 0;
    }
    &__form {
      display: flex;
      flex-direction: column;
      max-width: 600px;

      .dropdown-2 {
        width: 308px;
      }
    }

    &__btn-box {
      display: flex;
      gap: 16px;
      align-items: center;
    }
    &__title-box {
      display: flex;
      justify-content: space-between;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      width: 100%;
      &-btn {
        display: flex;
        align-self: center;
        gap: 10px;
        span {
          align-self: center;
        }
      }
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__more {
      display: flex;
      align-items: center;
      justify-content: space-between;
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        color: #3366ff;
      }
    }
  }
  &-form {
    max-width: 600px;
    box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
    border-radius: 4px;
    margin: 16px 12px 16px 0px;
  }
}
.optimization-option__list-item {
  padding: 12px 0;
  border-top: 1px solid #d6d6d6;
}
.optimization-option__btn-box {
  padding: 12px 0;
  border-top: 1px solid #d6d6d6;
}

.modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}

.modal-window {
  background: #fff;
  padding: 32px;
  border-radius: 6px;
  width: 380px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
}

.modal-title {
  font-size: 20px;
  font-weight: 700;
  color: #3366ff;
  padding-bottom: 24px;
  border-bottom: 1px solid #d6d6d6;
  margin-bottom: 16px;
}

.modal-actions {
  display: flex;
  gap: 16px;
}
</style>
